/**
 * Sprite de iconos del tema.
 *
 * Dos juegos en el mismo sprite: los de interfaz vienen de Coolicons (MIT) y
 * los médicos de UIcons de Flaticon, extraídos de la tipografía y convertidos a
 * trazados (ver CREDITOS.md). Todos a 24x24 y con currentColor.
 *
 * En la página solo se imprimen los símbolos que esa página realmente ocupa:
 * mandar los 128 en cada carga son 70 KB de los que se usan 18.
 *
 * @package MedMovil
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Iconos que se imprimen siempre, aunque el servidor no los haya dibujado.
 *
 * El JavaScript arma tarjetas en caliente (carrito, cotizador, sugerencias del
 * buscador, selector de zona) con el icono que tiene guardado cada prestación,
 * y esos <use> aparecen después de que el sprite ya se imprimió.
 *
 * @return array
 */
function medmovil_iconos_siempre() {
	return apply_filters( 'medmovil_iconos_siempre', array( 'il-eco', 'il-msk', 'il-dop', 'il-cardio', 'il-lab', 'il-rx', 'il-nurse', 'il-clockx' ) );
}

