	if ( function_exists( 'medmovil_iconos_lucide' ) ) {
		$simbolos = array_replace( $simbolos, medmovil_iconos_lucide() );
	}
	$base = $simbolos;

	if ( ! $con_propios ) {
		return $base;
	}

	// Los que el dueño cambió desde MedMóvil → Iconos pisan a los del tema.
	foreach ( medmovil_iconos_propios() as $id => $propio ) {
		if ( ! isset( $simbolos[ $id ] ) || empty( $propio['html'] ) ) {
			continue;
		}
		$simbolos[ $id ] = sprintf(
			'<symbol id="%s" viewBox="%s">%s</symbol>',
			esc_attr( $id ),
			esc_attr( isset( $propio['vb'] ) ? $propio['vb'] : '0 0 24 24' ),
			$propio['html']
		);
	}

	$mezclados = $simbolos;

	return $mezclados;
}

/**
 * Anota que la página necesita este icono.
 *
 * @param string $id Id del icono.
 */
function medmovil_marcar_icono( $id ) {
	$GLOBALS['medmovil_iconos_usados'][ $id ] = true;
}

/**
 * Imprime el sprite con los iconos que la página ocupó.
 */
function medmovil_sprite() {
	$disponibles = medmovil_simbolos();

	$pedidos = array_keys( (array) ( isset( $GLOBALS['medmovil_iconos_usados'] ) ? $GLOBALS['medmovil_iconos_usados'] : array() ) );
	$pedidos = array_unique( array_merge( $pedidos, medmovil_iconos_siempre() ) );

	$salida = '';
	foreach ( $pedidos as $id ) {
		if ( isset( $disponibles[ $id ] ) ) {
			$salida .= $disponibles[ $id ];
		}
	}

	if ( '' === $salida ) {
		return;
	}

	echo '<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs>'
		. $salida // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- SVG propio del tema.
		. '</defs></svg>';
}
